<?php $e=is_array($subcontract);$v=fn($k)=>(string)($subcontract[$k]??'');$locked=$e&&$v('status')!=='draft';?><h2 class="page-title mb-4"><?=e($title)?></h2><form class="card" method="post" action="<?=$e?'/subcontracts/'.$subcontract['id'].'/edit':'/subcontracts'?>"><div class="card-body"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><div class="row g-3"><div class="col-md-6"><label>المشروع</label><select class="form-select js-tom-select" name="project_id" <?=$locked?'disabled':''?>><?php foreach($projects as$x):?><option value="<?=$x['id']?>" <?=$v('project_id')==(string)$x['id']?'selected':''?>><?=e($x['project_code'].' - '.$x['name'])?></option><?php endforeach;?></select><?php if($locked):?><input type="hidden" name="project_id" value="<?=e($v('project_id'))?>"><?php endif;?></div><div class="col-md-6"><label>مقاول الباطن</label><select class="form-select js-tom-select" name="vendor_id" <?=$locked?'disabled':''?>><?php foreach($vendors as$x):if(!$x['is_active']&&$v('vendor_id')!==(string)$x['id'])continue;?><option value="<?=$x['id']?>" <?=$v('vendor_id')==(string)$x['id']?'selected':''?>><?=e($x['vendor_code'].' - '.$x['name'])?></option><?php endforeach;?></select><?php if($locked):?><input type="hidden" name="vendor_id" value="<?=e($v('vendor_id'))?>"><?php endif;?></div><?php foreach(['subcontract_number'=>'رقم العقد التجاري','title'=>'العنوان','contract_date'=>'تاريخ العقد','start_date'=>'تاريخ البدء','expected_end_date'=>'الانتهاء المتوقع','contract_value'=>'قيمة العقد']as$k=>$l):?><div class="col-md-6"><label><?=$l?></label><input class="form-control" name="<?=$k?>" <?=$k==='contract_date'||str_contains($k,'date')?'type="date"':''?> value="<?=e($v($k))?>" <?=($locked&&in_array($k,['subcontract_number','title','contract_date','contract_value']))?'readonly':''?>></div><?php endforeach;?><div class="col-md-6"><label>طريقة التسعير</label><select name="pricing_method" class="form-select" <?=$locked?'disabled':''?>><option value="boq">جدول كميات</option><option value="lump_sum" <?=$v('pricing_method')==='lump_sum'?'selected':''?>>مقطوعية</option></select><?php if($locked):?><input type="hidden" name="pricing_method" value="<?=e($v('pricing_method'))?>"><?php endif;?></div><div class="col-12"><textarea class="form-control" name="description" placeholder="الوصف" <?=$locked?'readonly':''?>><?=e($v('description'))?></textarea></div><div class="col-12"><textarea class="form-control" name="notes" placeholder="ملاحظات"><?=e($v('notes'))?></textarea></div></div></div><div class="card-footer"><button class="btn btn-primary">حفظ</button></div></form>
